node -e '
const r = require("./.context/lighthouse/baseline-mobile.report.json");
console.log("=== SCORES ===");
for (const [k,v] of Object.entries(r.categories)) console.log(String(Math.round(v.score*100)).padStart(3), k);
console.log("\n=== METRICS ===");
for (const m of ["first-contentful-paint","largest-contentful-paint","total-blocking-time","cumulative-layout-shift","speed-index"]) {
  const a = r.audits[m]; if(a) console.log((a.displayValue||"").padStart(10), "score="+a.score, m);
}
console.log("\n=== FAILING / IMPERFECT AUDITS ===");
for (const [id,a] of Object.entries(r.audits)) {
  if (a.score !== null && a.score < 1 && a.scoreDisplayMode !== "informative") {
    console.log(String(a.score).padEnd(6), id, "|", a.title);
  }
}
'

node -e '
const r = require("./.context/lighthouse/baseline-mobile.report.json");
const show = (id) => {
  const a = r.audits[id]; if (!a) return console.log("-- missing", id);
  console.log("\n##### "+id+" :: "+a.title+" (score "+a.score+")");
  if (a.displayValue) console.log("  ->", a.displayValue);
  const items = a.details?.items || [];
  console.log(JSON.stringify(items, null, 1).slice(0, 2600));
};
["errors-in-console","color-contrast","bf-cache","render-blocking-insight","largest-contentful-paint-element"].forEach(show);
'

