import { readFileSync } from "node:fs";

const r = JSON.parse(readFileSync(process.argv[2], "utf8"));

console.log("=== SCORES ===");
for (const [k, v] of Object.entries(r.categories)) {
  console.log(String(Math.round(v.score * 100)).padStart(4), k);
}

console.log("\n=== METRICS ===");
for (const m of [
  "first-contentful-paint",
  "largest-contentful-paint",
  "total-blocking-time",
  "cumulative-layout-shift",
  "speed-index",
]) {
  const a = r.audits[m];
  if (a) {
    console.log((a.displayValue || "").padStart(9), "score=" + a.score, m);
  }
}

console.log("\n=== FAILING WEIGHTED AUDITS ===");
let any = false;
for (const [cid, c] of Object.entries(r.categories)) {
  for (const ref of c.auditRefs) {
    const a = r.audits[ref.id];
    if (ref.weight > 0 && a.score !== null && a.score < 1) {
      any = true;
      console.log(
        `  ${cid.padEnd(14)} w=${String(ref.weight).padStart(3)} score=${String(a.score).padEnd(5)} ${ref.id}`
      );
    }
  }
}
if (!any) console.log("  (none)");

