() => {
  const rect = (el) => { const r = el.getBoundingClientRect(); return { w: Math.round(r.width), h: Math.round(r.height), top: Math.round(r.top), area: Math.round(r.width * r.height) }; };
  const h1 = document.querySelector('h1');
  const aside = document.querySelector('#hero-footnote-1 aside');
  const cs = (el) => { const c = getComputedStyle(el); return { fontFamily: c.fontFamily.slice(0, 60), opacity: c.opacity, animation: c.animationName + ' ' + c.animationDuration + ' delay ' + c.animationDelay }; };
  return {
    h1: h1 ? { text: h1.textContent.slice(0, 60), ...rect(h1), ...cs(h1) } : null,
    aside: aside ? { text: aside.textContent.slice(0, 50), ...rect(aside), ...cs(aside) } : null,
    fontsLoaded: document.fonts.status,
    loadedFaces: [...document.fonts].map(f => f.family + ':' + f.weight + ':' + f.status),
  };
}

