# Variant: h1 slides but never starts transparent, so it is paintable at first paint.
p = "apps/web/app/[locale]/components/hero.tsx"
s = open(p).read()
s = s.replace('className="ht-enter max-w-4xl font-display', 'className="ht-enter-opaque max-w-4xl font-display')
