c = "apps/web/app/styles.css"
s = open(c).read()
anchor = """@media (prefers-reduced-motion: no-preference) {
  .ht-enter {
    animation: ht-rise 700ms cubic-bezier(0.16, 1, 0.3, 1) both;
    animation-delay: var(--ht-delay, 0ms);
  }
}"""
new = anchor + """

/* The headline joins the same movement but never starts transparent. It is the
   largest thing in the hero, so while it fades it is not a paint the browser
   will count, and Largest Contentful Paint waits out the whole 700ms for a
   headline that was already in the HTML. Sliding it in at full opacity keeps
   the choreography and lets the paint count immediately. */
@media (prefers-reduced-motion: no-preference) {
  .ht-enter-opaque {
    animation: ht-slide 700ms cubic-bezier(0.16, 1, 0.3, 1) both;
    animation-delay: var(--ht-delay, 0ms);
  }
}

@keyframes ht-slide {
  from {
    transform: translateY(0.75rem);
  }
  to {
    transform: none;
  }
}"""
s = s.replace(anchor, new)
open(c, "w").write(s)
